// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, address recipient) public {
        vm.assume(sender != address(c));
        vm.assume(recipient != address(c));
        vm.assume(sender != recipient);

        uint256 initialBalance = address(c).balance;
        vm.deal(address(c), 1 ether);

        vm.prank(sender);
        bool reverted = false;
        try c.withdrawAll(recipient) {
            // success
        } catch {
            reverted = true;
        }

        // After call, check if balance changed only when called by non-owner (msg.sender != owner)
        // Reference: only owner can call successfully and transfer balance; non-owner reverts.
        // Bug: only non-owner can call successfully and transfer balance; owner reverts.
        // So the rule: if sender is owner (address(this)), the call must revert in bug (but not in reference) – wait, need general rule.
        // Actually, the invariant: The balance after call is unchanged if and only if the call reverted or was called by owner (reference) / non-owner (bug).
        // Better: For the reference, the balance is transferred (changed) only when msg.sender == owner and call succeeds.
        // Since we can't distinguish success/revert directly here, use: balance after call == initialBalance + 1 ether (added) - transferAmount if succeeded and sender is owner.
        // Simpler: The call should revert if sender != owner in reference, else it succeeds and balance becomes 0.
        // So assert: (sender == owner && !reverted && address(c).balance == 0) || (sender != owner && reverted && address(c).balance == 1 ether)
        assertTrue(
            (sender == address(this) && !reverted && address(c).balance == 0) ||
            (sender != address(this) && reverted && address(c).balance == 1 ether),
            "property failed"
        );
    }
}

